# -*- coding: utf-8 -*-
import json
from pathlib import Path
from lesson_authoring import entry as E
A=[['希腊语 Akadēmeia／Akadēmia','雅典城外的一处园林及活动场所；名称传统上与传说人物 Akademos 相连'],['柏拉图在此讲学 → 拉丁 Academia','地点名成为学园和学派名']]
AC=A+[['希腊 akadēmikos → 拉丁 academicus；也经法语 académique','属于学园、学术的'],['英语 academic','学术的、学业的；大学学者；只停留在理论上的']]
W=[
E('academic','/ˌækəˈdemɪk/','学术的；学业的；理论上的；大学学者','先想大学里的研究、论文和课程；有时再往前一步，指讨论停在纸面上，对眼前的决定没影响。','现代可以联系 academy 与 -ic“相关的”；历史已有希腊、拉丁形容词，也有法语借入途径。',AC,'academic research 是学术研究，academic performance 是学业表现。说 That question is academic，常是在说“理论上可以争，但现在已经不影响结果了”。这不是在否定一切学术，只是这个问题在当下没有实际作用。名词 an academic 则是大学里的教学或研究人员。','academic writing；academic year；academic performance；a purely academic question。','scholarly 更突出学者式的研究和知识；academic 还常修饰学业、学年。an academic 通常不能自动翻成“院士”。',('Her academic performance improved after she changed her study routine.','她调整学习习惯后，学业表现提高了。'),('The tickets are sold out, so the question of which seats to choose is now academic.','票已经卖完了，所以现在讨论选哪个座位已经没有实际意义了。'),('The report was written by two academics and a journalist.','这份报告由两位大学学者和一位记者撰写。'),sources=['https://www.etymonline.com/word/academic','https://en.wiktionary.org/wiki/academic']),
E('academy','/əˈkædəmi/','学院；专门训练学校；学会、研究院等机构','从“大家来这里讲学的那个地方”，发展成专门培养人才或汇聚专业人士的机构。','academy 是整词传入，不应拆成 a- + cademy。源头是希腊的地点名 Akadēmeia。',A+[['拉丁 Academia，经法语或直接传入英语','古典学园'],['英语 academy','学校、训练机构；学术或艺术团体']],'academy 可以是训练人的地方，如 police academy；也可以是聚集专业成员的团体，如 an academy of sciences。机构叫 academy，并不能单凭这个名字判定它一定是大学、一定授予学位；要看具体机构。','a music academy；a police academy；an academy of sciences。','school 范围很广；academy 常带专门训练或专业团体色彩。Academy Awards 中的 Academy 指颁奖机构的名称，不能翻成“学校奖”。',('He trained at a music academy before joining the orchestra.','加入乐团前，他在一所音乐学院接受训练。'),('The academy elected five new members this year.','这个学会今年选出了五位新成员。'),sources=['https://www.etymonline.com/word/academy','https://en.wiktionary.org/wiki/academy']),
E('academia','/ˌækəˈdiːmiə/','学术界；高校教学与研究领域','把大学、研究人员、论文、教学和相关职业，整体看成一个工作与生活圈。','借自新拉丁语 academia，与 academy 同源；不要把它硬拆成英语 academic 去 c 再添 a。',A+[['新拉丁语 academia → 英语 academia','以拉丁形式进入英语'],['现代常用义 academia','高校与学术研究的整体领域']],'academia 通常不是某一所学院，而是整个学术圈。leave academia 常指离开大学教学研究这条职业路线，转到企业等领域；不等于从此不读书、不研究。它一般不可数，不说 an academia 来指一所学校。','work in academia；a career in academia；leave academia；outside academia。','academy 是具体机构；academia 是领域或圈子；an academic 是其中的一位学者。三者不是可以随意替换的长短写法。',('After ten years in academia, she joined a technology company.','在学术界工作十年后，她加入了一家科技公司。'),('The project brings together people from academia and industry.','这个项目把学术界和产业界的人聚到了一起。'),sources=['https://www.etymonline.com/word/academia','https://en.wiktionary.org/wiki/academia']),
E('academically','/ˌækəˈdemɪkəli/，也常读 /ˌækəˈdemɪkli/','在学业上；在学术上；从理论上说','把评价范围圈在学习、研究或理论这一面，而不是对整个人作总评价。','academic + -ally；也可经 academical + -ly 分析。结尾 -ically 常读 /ɪkli/。',AC+[['academic／academical + 副词后缀','academically：从学业或学术这一方面看']],'do well academically 是学业表现好；academically rigorous 是研究或教学在学术上严谨。说一个学生 struggles academically，只说明学习方面有困难，不能顺便推出他在其他事情上也做不好。','do well academically；struggle academically；academically rigorous。','academic 是形容词或名词；academically 常修饰动词或形容词。academically strong 指学业方面强，不是身体强壮。',('The school offers extra support to students who are struggling academically.','学校为学业上遇到困难的学生提供额外支持。'),('The course is academically demanding but very rewarding.','这门课在学术上要求很高，但也很有收获。'),sources=['https://en.wiktionary.org/wiki/academically','https://www.etymonline.com/word/academic']),
E('academician','/ˌækədəˈmɪʃən/','学术或艺术机构的成员；院士；学者〔较正式〕','重点常在“被某个学术或艺术团体接纳为正式成员”，不只是“在大学里工作”。','现代可联系 academic + -ian；英语历史也借入法语 académicien，不能只讲成英语临时加后缀。',A+[['法语 académique + -ien → académicien','学术或艺术团体的成员'],['英语 academician','相关机构的正式成员，也可泛指学者']],'在一些机构语境里 academician 可以译为院士；在艺术学会里也可能指正式成员。翻译要跟着机构身份走，不能看到这个词就认定是某一国家科学院的院士。泛指大学教师或研究者时，academic 通常更平常。','an academician of an academy；be elected an academician。','academic 是较宽的学者称呼；academician 常突出机构成员身份。professor 是教授职称，不自动等于 academician。',('She was elected an academician after years of work in sculpture.','从事雕塑多年后，她当选为该艺术院的正式成员。'),('The conference included both academicians and young researchers.','会议既有院士参加，也有年轻研究人员参加。'),sources=['https://www.merriam-webster.com/dictionary/academician','https://en.wiktionary.org/wiki/academician']),
]
ROOT=dict(id='C0005',meaning='从雅典学园到学校、学术与学业',core='ACADEM = ACADEMY',image='一个讲学地点的名字，逐渐变成学校、学者和学术世界的共同标记。',intro='academ- 并不是一开始就表示“知识”的抽象小零件。它来自希腊地名 Akadēmeia，传统上与传说人物 Akademos 相连。柏拉图在那里讲学，地点名成了学园名，后来才扩展到一般学校和学术领域。',forms='academy 指机构；academic 指相关性质或学者；academia 指整个学术界。这些形式有不同的希腊、拉丁或法语传入路线，不能全部画成现代 academy 一个接一个变出来。academically 是副词，academician 常是专业机构成员。',branches=[['机构与整体领域','academy, academia'],['学习、研究与评价','academic, academically'],['学术或艺术机构成员','academician']],contrasts='academic 不只有“高深学术”一个意思，也能谈普通学生的学业。purely academic 有时意味着理论上可谈、实际已无影响。academy 是机构，academia 是圈子，an academic 是人。',practice='She works at an academy, hopes to stay in academia, and has published several academic papers.\n\n她在一所学院工作，希望留在学术界，也已经发表了几篇学术论文。',words=[w['word'] for w in W],exclude={'academe':'文学性、较少用的同族形式，按用户最新要求暂缓。'})
if __name__=='__main__':
 for name,data in [('roots_academ',[ROOT]),('words_academ',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),'words',sum(len(w['examples']) for w in W),'examples')
